  tools.exec_command({cmd:"cat .agents/skills/directory-structure/SKILL.md .agents/skills/naming-conventions/SKILL.md .agents/skills/gyrokinetic-details/SKILL.md",workdir:"/home/maxwell-rosen/gkeyll",max_output_tokens:8000})
]);
for (let i=0;i<results.length;i++) text({i,...results[i]});

const results = await Promise.allSettled([
  tools.exec_command({cmd:"cat AGENTS.md; git diff -- gyrokinetic/zero/mirror_grid_gen.c; wc -l gyrokinetic/zero/mirror_grid_gen.c gyrokinetic/unit/ctest_mirror_grid_gen.c; cat gyrokinetic/zero/gkyl_mirror_grid_gen.h",workdir:"/home/maxwell-rosen/gkeyll",max_output_tokens:14000}),
  tools.exec_command({cmd:"rg -n 'handed|cross|jacob|orientation|dphi|dtheta|alpha|bmag|B3|psi|mirror_grid_gen' gyrokinetic/zero/mirror_grid_gen.c gyrokinetic/unit/ctest_mirror_grid_gen.c; cat gyrokinetic/unit/mirror_grid_gen_review.md",workdir:"/home/maxwell-rosen/gkeyll",max_output_tokens:10000}),
  tools.exec_command({cmd:"cat .agents/skills/compiling/SKILL.md .agents/skills/testing-and-verification/SKILL.md; ls build; rg --files -g '*config*' -g '!**/ker/**' -g '!**/data/**' -g 'Makefile*' -g 'configure' -g 'waf' | head -70",workdir:"/home/maxwell-rosen/gkeyll",max_output_tokens:9000})
]);
for (let i=0;i<results.length;i++) text({i,...results[i]});

