# Gkeyll agent instructions

## Role

You are a computational plasma physicist working on Gkeyll (Gkeyll solves partial differential
equations). You are:
- a critical thinker,
- analytical and precise,
- an assistant that communicates concisely,
- well versed in plasma physics and numerical methods for partial differential
  equations (both traditional and data-driven).

Your responsibilities are to increase the capabilities of the Gkeyll codebase, elevate the quality
of its software, identify bugs and other issues, troubleshoot and make suggestions to your colleagues.

## Core directives

- Stick to the task colleagues pointed you to, but stay vigilant for bugs and
  issues you identify along the way that may not be related to your task.
- New and edited code should prioritize correctness, performance,
  maintainability and simplicity, in that order (from most to least important).
- Test and verify new and edited code.
- Take into consideration the ideas and guidelines colleagues give you, but be
  creative and suggest alternative approaches.

## Skills and detailed instructions

Before performing a task, read the corresponding skill. Load only skills
needed for the current task; multiple skills may apply, but do not preload every skill.

All paths below are relative to the repository root, regardless of the current
working directory. Links inside a skill are relative to that skill's directory.

| Work | Relevant skill |
| --- | --- |
| Locate code or decide where it belongs | [Directory structure](.agents/skills/directory-structure/SKILL.md) |
| Create or modify modules in `zero/` or `apps/` | [Software design](.agents/skills/software-design/SKILL.md) |
| Create, edit, or review C, CUDA, or Lua code | [Naming conventions](.agents/skills/naming-conventions/SKILL.md) |
| Compile libraries, tests, or input files | [Compiling](.agents/skills/compiling/SKILL.md) |
| Run tests, simulations, or memory checks | [Testing and verification](.agents/skills/testing-and-verification/SKILL.md) |
| Work on the gyrokinetic solver or its input files | [Gyrokinetic details](.agents/skills/gyrokinetic-details/SKILL.md) |

diff --git a/gyrokinetic/zero/mirror_grid_gen.c b/gyrokinetic/zero/mirror_grid_gen.c
index 35abee02f..a2699586e 100644
--- a/gyrokinetic/zero/mirror_grid_gen.c
+++ b/gyrokinetic/zero/mirror_grid_gen.c
@@ -222,7 +222,7 @@ static struct gkyl_mirror_grid_gen *mggen_new(const struct gkyl_mirror_grid_gen_
           geom->tang[NAL].x[PHI_I] = dAlpha_dalpha;
           geom->tang[NZ].x[Z_I] = dZ_dz;
           geom->Jc = sqrt_psi ? 0.0 : dPsi_dpsi * dAlpha_dalpha * dZ_dz / fout[D2PSI_RR_I];
-          geom->B.x[Z_I] = -fout[D2PSI_RR_I];
+          geom->B.x[Z_I] = fout[D2PSI_RR_I];
         } else {
           double fout[3];
           evcub->eval_cubic_wgrad(0.0, rz, fout, evcub->ctx);
@@ -238,8 +238,8 @@ static struct gkyl_mirror_grid_gen *mggen_new(const struct gkyl_mirror_grid_gen_
           geom->tang[NZ].x[R_I] = -fout[DPSI_Z_I] / fout[DPSI_R_I] * dZ_dz;
           geom->tang[NZ].x[Z_I] = dZ_dz;
           geom->Jc = radial_scale * radius / fout[DPSI_R_I] * dAlpha_dalpha * dZ_dz;
-          geom->B.x[R_I] = fout[DPSI_Z_I] / radius;
-          geom->B.x[Z_I] = -fout[DPSI_R_I] / radius;
+          geom->B.x[R_I] = -fout[DPSI_Z_I] / radius;
+          geom->B.x[Z_I] = fout[DPSI_R_I] / radius;
           curlbhat_func(radius, zcurr, alpha_curr, evcub, &geom->curlbhat);
         }
       }
  294 gyrokinetic/zero/mirror_grid_gen.c
 1025 gyrokinetic/unit/ctest_mirror_grid_gen.c
 1319 total
#pragma once

#include <gkyl_array.h>
#include <gkyl_math.h>
#include <gkyl_rect_grid.h>
#include <gkyl_range.h>
#include <gkyl_position_map.h>

// Forward declare internal object
struct gkyl_mirror_grid_gen_x;

// Geometric quantities: vectors use contravariant (R, phi, Z) components,
// as required by gkyl_vec3_polar_con_to_cart. Positions in nodes_rza use
// cylindrical coordinate order (R, Z, phi).
struct gkyl_mirror_grid_gen_geom {
  struct gkyl_vec3 tang[3]; // tangent vectors, e_i
  struct gkyl_vec3 dual[3]; // dual vectors, e^i
  struct gkyl_vec3 B; // Magnetic field: B_R = psi_Z/R, B_Z = -psi_R/R, B_phi = 0.
  double Jc; // Jacobian = e_1*(e_2 X e_3)  = 1/e^1*(e^2 X e^3)
  struct gkyl_vec3 curlbhat; // \nabla X \hat{b}
};

struct gkyl_mirror_grid_gen {
  struct gkyl_array *nodes_rza; // r,z,phi coordinates of corner nodes of cells
  struct gkyl_array *nodes_psi; // psi values at nodes
  struct gkyl_array *nodes_geom; // geometric quantities at nodes:
  // this is an array of gkyl_mirror_grid_gen_geom objects

  struct gkyl_mirror_grid_gen_x *gg_x; // Internal object that contains flags
  // describing the type of geometry being generated
};

// flag to indicate what field-line coordinate to use
enum gkyl_mirror_grid_gen_field_line_coord {
  GKYL_GEOMETRY_MIRROR_GRID_GEN_PSI_CART_Z, // use psi and Cartesian Z coordinate
  GKYL_GEOMETRY_MIRROR_GRID_GEN_SQRT_PSI_CART_Z // use sqrt(psi) and Cartesian Z coordinate
};

// input struct to construct the mirror geometry
struct gkyl_mirror_grid_gen_inp {
  const struct gkyl_rect_grid *comp_grid; // Computational space grid (psi, phi, z)
  const struct gkyl_range nrange; // Nodal range
  const struct gkyl_range local; // local range
  const struct gkyl_range global; //global range
  int dir; // Surface direction
  const struct gkyl_position_map *position_map; // position map
  enum gkyl_mirror_grid_gen_field_line_coord fl_coord; // field-line coordinate to use
  bool include_axis; // add nodes on r=0 axis (the axis is assumed be psi=0)

  double R[2], Z[2]; // extents of R,Z grid on which psi(R,Z) is given
  int nrcells, nzcells; // number of cells in R and Z
  const struct gkyl_array *psiRZ; // nodal values of psi(R,Z)

  bool write_psi_cubic; // set to true to write the cubic fit to file
  const char *psi_cubic_fname; // name for cubic fit file
};

/**
 * Create new grid generator for mirror geometries. Return a NULL
 * pointer if the grid generator failed.
 *
 * @param inp Input parameters to the grid generator
 * @return newly create mirror geometry object
 */
struct gkyl_mirror_grid_gen *gkyl_mirror_grid_gen_inew(const struct gkyl_mirror_grid_gen_inp *inp);

struct gkyl_mirror_grid_gen *
gkyl_mirror_grid_gen_int_inew(const struct gkyl_mirror_grid_gen_inp *inp);

struct gkyl_mirror_grid_gen *
gkyl_mirror_grid_gen_surf_inew(const struct gkyl_mirror_grid_gen_inp *inp);

/**
 * Does the grid include the axis?
 *
 * @param geom Geometry object
 * @return true if axis is included, false otherwise.
 */
bool gkyl_mirror_grid_gen_is_include_axis(const struct gkyl_mirror_grid_gen *geom);

/**
 * Get field-line coordinate used in grid
 *
 * @param geom Geometry object
 * @return field-line coordinate used in grid
 */
enum gkyl_mirror_grid_gen_field_line_coord
gkyl_mirror_grid_gen_fl_coord(const struct gkyl_mirror_grid_gen *geom);

/**
 * Release the mirror grid object.
 *
 * @param geom Mirror grid object to release
 */
void gkyl_mirror_grid_gen_release(struct gkyl_mirror_grid_gen *geom);

