    55	  double Br = 0.0, Bz = 0.0, bmag = 0.0;
    56	  double dpsidR = 0.0, dpsidZ = 0.0;
    57	  double d2psidR2 = 0.0, d2psidZ2 = 0.0, d2psidRdZ = 0.0;
    58	  double dBdR = 0.0, dBdZ = 0.0;
    59	  double dBrdR = 0.0, dBrdZ = 0.0;
    60	  double dBzdR = 0.0, dBzdZ = 0.0;
