    62	  double xn[2] = {r_curr, Z};
    63	  double fout[4];
    64	  evcub->eval_cubic_wgrad(0.0, xn, fout, evcub->ctx);
    65	  dpsidR = fout[DPSI_R_I];
    66	  dpsidZ = fout[DPSI_Z_I];
    67	  evcub->eval_cubic_wgrad2(0.0, xn, fout, evcub->ctx);
    68	  d2psidR2 = fout[D2PSI_RR_I];
    69	  d2psidZ2 = fout[D2PSI_ZZ_I];
    70	  d2psidRdZ = fout[D2PSI_RZ_I];
    71	
    72	  // Same poloidal-field convention as tok_geo.c.
    73	  Br = dpsidZ / r_curr;
    74	  Bz = -dpsidR / r_curr;
    75	  bmag = sqrt(Br * Br + Bz * Bz);
    76	
    77	  dBrdR = d2psidRdZ / r_curr - Br / r_curr;
    78	  dBrdZ = d2psidZ2 / r_curr;
    79	  dBzdR = -d2psidR2 / r_curr - Bz / r_curr;
    80	  dBzdZ = -d2psidRdZ / r_curr;
