   147	      pmap, NZ, zcomp, comp_grid.dx[NZ], comp_grid.lower[NZ], comp_grid.upper[NZ]
   148	    );
   149	    double psi_min, psi_max;
   150	    evcub->eval_cubic(0.0, (double[]){rmin, zcurr}, &psi_min, evcub->ctx);
   151	    evcub->eval_cubic(0.0, (double[]){rmax, zcurr}, &psi_max, evcub->ctx);
   152	    pctx.Z = zcurr;
   153	
   154	    for (int ipsi = inp->nrange.lower[NPSI]; ipsi <= inp->nrange.upper[NPSI]; ++ipsi) {
   155	      double psic = gk_geometry_node_coord(
   156	        &comp_grid, &inp->local, &inp->global, &inp->nrange, NPSI, ipsi, num_nodes[NPSI], quad[NPSI]
   157	      );
   158	      double psi_map;
   159	      pmap->maps[NPSI](0.0, &psic, &psi_map, pmap->ctxs[NPSI]);
   160	      double dPsi_dpsi = gkyl_position_map_slope(
   161	        pmap, NPSI, psic, comp_grid.dx[NPSI], comp_grid.lower[NPSI], comp_grid.upper[NPSI]
   162	      );
   163	      double psi_curr = sqrt_psi ? psi_map * psi_map : psi_map;
   164	      bool on_axis = inp->include_axis && !quad[NPSI] && ipsi == inp->nrange.lower[NPSI] &&
   165	                     inp->local.lower[NPSI] == inp->global.lower[NPSI];
   166	      double radius = 0.0;
   167	      if (on_axis) {
   168	        psi_curr = 0.0;
   169	      } else {
   170	        pctx.psi = psi_curr;
   171	        double f_lo = psi_min - psi_curr, f_hi = psi_max - psi_curr;
   172	        double psi_tol = 16.0 * DBL_EPSILON * fabs(psi_curr);
   173	        // Ridders requires a bracket. Without one it can report convergence
   174	        // to an extrapolated radius (or even a point that is not a root).
   175	        // Accept endpoint roots to roundoff before checking the signs.
   176	        if (fabs(f_lo) <= psi_tol) {
   177	          radius = rmin;
   178	        } else if (fabs(f_hi) <= psi_tol) {
   179	          radius = rmax;
   180	        } else if ((f_lo < 0.0 && f_hi > 0.0) || (f_lo > 0.0 && f_hi < 0.0)) {
   181	          struct gkyl_qr_res root = gkyl_ridders(psirz, &pctx, rmin, rmax, f_lo, f_hi, 100, 1e-10);
   182	          if (root.status || !(root.res >= rmin && root.res <= rmax)) {
   183	            status = false;
   184	            goto cleanup;
   185	          }
   186	          radius = root.res;
   187	        } else {
   188	          status = false;
   189	          goto cleanup;
   190	        }
   191	      }
   192	
   193	      for (int ia = inp->nrange.lower[NAL]; ia <= inp->nrange.upper[NAL]; ++ia) {
   194	        double alpha_comp = gk_geometry_node_coord(
   195	          &comp_grid, &inp->local, &inp->global, &inp->nrange, NAL, ia, num_nodes[NAL], quad[NAL]
   196	        );
   197	        double alpha_curr;
   198	        pmap->maps[NAL](0.0, &alpha_comp, &alpha_curr, pmap->ctxs[NAL]);
   199	        double dAlpha_dalpha = gkyl_position_map_slope(
   200	          pmap, NAL, alpha_comp, comp_grid.dx[NAL], comp_grid.lower[NAL], comp_grid.upper[NAL]
   201	        );
   202	        int idx[] = {ipsi, ia, iz};
   203	        long loc = gkyl_range_idx(&inp->nrange, idx);
   204	        double *rzp = gkyl_array_fetch(geo->nodes_rza, loc);
   205	        rzp[R_NODE_I] = radius;
   206	        rzp[Z_NODE_I] = zcurr;
   207	        rzp[PHI_NODE_I] = alpha_curr;
   208	        double *psi_coord = gkyl_array_fetch(geo->nodes_psi, loc);
   209	        psi_coord[PSI_I] = psi_curr;
   210	        struct gkyl_mirror_grid_gen_geom *geom = gkyl_array_fetch(geo->nodes_geom, loc);
   211	        *geom = (struct gkyl_mirror_grid_gen_geom){0};
   212	        double rz[] = {radius, zcurr};
   213	        if (on_axis) {
   214	          double fout[4];
   215	          evcub->eval_cubic_wgrad2(0.0, rz, fout, evcub->ctx);
   216	          // The radial/poloidal basis is singular at the axis. Keep the
   217	          // existing defaults and the asymptotic psi ~ R^2 Jacobian.
   218	          geom->dual[NPSI].x[R_I] = 1.0 / dPsi_dpsi;
   219	          geom->dual[NAL].x[PHI_I] = 1.0 / dAlpha_dalpha;
   220	          geom->dual[NZ].x[Z_I] = 1.0 / dZ_dz;
   221	          geom->tang[NPSI].x[R_I] = dPsi_dpsi;
   222	          geom->tang[NAL].x[PHI_I] = dAlpha_dalpha;
   223	          geom->tang[NZ].x[Z_I] = dZ_dz;
   224	          geom->Jc = sqrt_psi ? 0.0 : dPsi_dpsi * dAlpha_dalpha * dZ_dz / fout[D2PSI_RR_I];
   225	          geom->B.x[Z_I] = fout[D2PSI_RR_I];
   226	        } else {
   227	          double fout[3];
   228	          evcub->eval_cubic_wgrad(0.0, rz, fout, evcub->ctx);
   229	          double radial_scale = dPsi_dpsi * (sqrt_psi ? 2.0 * floor_sqrt(fout[PSI_I]) : 1.0);
   230	          geom->dual[NPSI].x[R_I] = fout[DPSI_R_I] / radial_scale;
   231	          geom->dual[NPSI].x[Z_I] = fout[DPSI_Z_I] / radial_scale;
   232	          geom->dual[NAL].x[PHI_I] = 1.0 / (radius * radius * dAlpha_dalpha);
   233	          geom->dual[NZ].x[Z_I] = 1.0 / dZ_dz;
   234	          geom->tang[NPSI].x[R_I] = radial_scale / fout[DPSI_R_I];
   235	          geom->tang[NAL].x[PHI_I] = dAlpha_dalpha;
   236	          // R(psi, M(z)): both components of the field-line tangent
   237	          // carry dM/dz. This preserves e_3 dot grad(psi) = 0.
   238	          geom->tang[NZ].x[R_I] = -fout[DPSI_Z_I] / fout[DPSI_R_I] * dZ_dz;
   239	          geom->tang[NZ].x[Z_I] = dZ_dz;
   240	          geom->Jc = radial_scale * radius / fout[DPSI_R_I] * dAlpha_dalpha * dZ_dz;
   241	          geom->B.x[R_I] = -fout[DPSI_Z_I] / radius;
   242	          geom->B.x[Z_I] = fout[DPSI_R_I] / radius;
   243	          curlbhat_func(radius, zcurr, alpha_curr, evcub, &geom->curlbhat);
   244	        }
   245	      }
   246	    }
   247	  }
   248	
   249	cleanup:
   250	  gkyl_dg_basis_ops_evalf_release(evcub);
   251	  if (!status) {
   252	    gkyl_mirror_grid_gen_release(geo);
   253	    fprintf(stderr, "gkyl_mirror_grid_gen failed to generate a grid\n");
   254	    return 0;
   255	  }
   256	  return geo;
   257	}
   258	
   259	struct gkyl_mirror_grid_gen *gkyl_mirror_grid_gen_inew(const struct gkyl_mirror_grid_gen_inp *inp)
   260	{
   261	  return mggen_new(inp, -1);
   262	}
