struct gk_geometry *gk_geometry_mirror_init(struct gkyl_gk_geometry_inp *geometry_inp)
{
  struct gk_geometry *up = gkyl_malloc(sizeof(struct gk_geometry));
  up->geometry_id = geometry_inp->geometry_id;
  up->basis = geometry_inp->geo_basis;
  up->local = geometry_inp->geo_local;
  up->local_ext = geometry_inp->geo_local_ext;
  up->global = geometry_inp->geo_global;
  up->global_ext = geometry_inp->geo_global_ext;
  up->grid = geometry_inp->geo_grid;
  up->geqdsk_sign_convention =
    0.0; // Hardcoded 0. Means psi increases from axis. Always true for mirror geometry.
  up->half_domain = 0;
  up->has_LCFS = false; // MF 2025/09/19: Hardcodded for now.

  // Initialize nodal ranges for corner, interior, and surface geometry
  gk_geometry_set_nodal_ranges(up);
  // Initialize surface basis
  gkyl_cart_modal_serendip(&up->surf_basis, up->grid.ndim - 1, up->basis.poly_order);
  up->num_surf_basis = up->surf_basis.num_basis;
  // Allocate nodal and modal arrays for corner, interior, and surface geo
  gk_geometry_corn_alloc_nodal(up);
  gk_geometry_corn_alloc_expansions(up);
  gk_geometry_int_alloc_nodal(up);
  gk_geometry_int_alloc_expansions(up);
  for (int dir = 0; dir < up->grid.ndim; ++dir) {
    gk_geometry_surf_alloc_nodal(up, dir);
    gk_geometry_surf_alloc_expansions(up, dir);
  }

  // read psi(R,Z) from file
  struct gkyl_rect_grid psi_grid;
  struct gkyl_array *psi =
    gkyl_grid_array_new_from_file(&psi_grid, geometry_inp->mirror_grid_info.filename_psi);

  // Check if file exists using gkyl_check_file_exists and handle error only on rank 0
  if (!gkyl_check_file_exists(geometry_inp->mirror_grid_info.filename_psi)) {
    fprintf(
      stderr, "Failed to open the eqdsk file: %s\n", geometry_inp->mirror_grid_info.filename_psi
    );
    assert(false);
  }

  gkyl_position_map_optimize(geometry_inp->position_map, up->grid, up->global);

  // Create mirror geometry for corners.
  struct gkyl_mirror_grid_gen *mirror_grid_corn = gkyl_mirror_grid_gen_inew(
    &(struct gkyl_mirror_grid_gen_inp){.comp_grid = &up->grid,
                                       .nrange = up->nrange_corn,
                                       .local = up->local,
                                       .global = up->global,
                                       .position_map = geometry_inp->position_map,

                                       .R = {psi_grid.lower[0], psi_grid.upper[0]},
                                       .Z = {psi_grid.lower[1], psi_grid.upper[1]},

                                       // psi(R,Z) grid size
                                       .nrcells = psi_grid.cells[0] - 1, // Cells and not nodes.
                                       .nzcells = psi_grid.cells[1] - 1, // Cells and not nodes.

                                       .psiRZ = psi,
                                       .fl_coord = geometry_inp->mirror_grid_info.fl_coord,
                                       .include_axis = geometry_inp->mirror_grid_info.include_axis,
                                       .write_psi_cubic = false}
  );

  // Create mirror geometry for interior.
  struct gkyl_mirror_grid_gen *mirror_grid_int = gkyl_mirror_grid_gen_int_inew(
    &(struct gkyl_mirror_grid_gen_inp){.comp_grid = &up->grid,
                                       .nrange = up->nrange_int,
                                       .local = up->local,
                                       .global = up->global,
                                       .position_map = geometry_inp->position_map,

                                       .R = {psi_grid.lower[0], psi_grid.upper[0]},
                                       .Z = {psi_grid.lower[1], psi_grid.upper[1]},

                                       // psi(R,Z) grid size.
                                       .nrcells = psi_grid.cells[0] - 1, // Cells and not nodes.
                                       .nzcells = psi_grid.cells[1] - 1, // Cells and not nodes.

                                       .psiRZ = psi,
                                       .fl_coord = geometry_inp->mirror_grid_info.fl_coord,
                                       .include_axis = geometry_inp->mirror_grid_info.include_axis,
                                       .write_psi_cubic = false}
  );

  // create mirror geometry for surfaces
  struct gkyl_mirror_grid_gen *mirror_grid_surf[3];
  for (int dir = 0; dir < up->grid.ndim; dir++) {
    mirror_grid_surf[dir] = gkyl_mirror_grid_gen_surf_inew(&(
      struct gkyl_mirror_grid_gen_inp
    ){.comp_grid = &up->grid,
      .nrange = up->nrange_surf[dir],
      .local = up->local,
      .global = up->global,
      .dir = dir,
      .position_map = geometry_inp->position_map,

      .R = {psi_grid.lower[0], psi_grid.upper[0]},
      .Z = {psi_grid.lower[1], psi_grid.upper[1]},

      // psi(R,Z) grid size.
      .nrcells = psi_grid.cells[0] - 1, // Cells and not nodes.
      .nzcells = psi_grid.cells[1] - 1, // Cells and not nodes.

      .psiRZ = psi,
      .fl_coord = geometry_inp->mirror_grid_info.fl_coord,
      .include_axis = geometry_inp->mirror_grid_info.include_axis,
      .write_psi_cubic = false});
  }

  // Now calculate the derived geometric coefficients at necessary nodes and compute modal expansions where required.
  // Now calculate the metrics at corner and interior nodes.
  struct gkyl_calc_metric_mirror *mcalc =
    gkyl_calc_metric_mirror_new(&up->basis, &up->grid, &up->local, &up->local_ext, false);
  gkyl_calc_metric_mirror_advance(mcalc, up, mirror_grid_corn);

item.formatted_output:
  // The input radial bounds are psi bounds; this option samples uniformly
  // in sqrt(psi), before applying any user radial position map.
  struct gkyl_rect_grid comp_grid = *inp->comp_grid;
  bool sqrt_psi = inp->fl_coord == GKYL_GEOMETRY_MIRROR_GRID_GEN_SQRT_PSI_CART_Z;
  if (sqrt_psi) {
    comp_grid.lower[NPSI] = inp->include_axis ? 0.0 : sqrt(comp_grid.lower[NPSI]);
    comp_grid.upper[NPSI] = sqrt(comp_grid.upper[NPSI]);
    comp_grid.dx[NPSI] = (comp_grid.upper[NPSI] - comp_grid.lower[NPSI]) / comp_grid.cells[NPSI];
  }
  bool quad[3];
  int num_nodes[3];
  for (int dim = 0; dim < 3; ++dim) {
    quad[dim] = kind == -2 || (kind >= 0 && kind != dim);
    num_nodes[dim] = (gkyl_range_shape(&inp->nrange, dim) - (quad[dim] ? 0 : 1)) /
                     gkyl_range_shape(&inp->local, dim);
  }

  const struct gkyl_position_map *pmap = inp->position_map;
  double rmin = inp->R[0] + 1e-8 * (inp->R[1] - inp->R[0]), rmax = inp->R[1];
  struct psirz_ctx pctx = {.evcub = evcub};
  bool status = true;
  for (int iz = inp->nrange.lower[NZ]; iz <= inp->nrange.upper[NZ]; ++iz) {
    double zcomp = gk_geometry_node_coord(
      &comp_grid, &inp->local, &inp->global, &inp->nrange, NZ, iz, num_nodes[NZ], quad[NZ]
    );
    double zcurr;
    pmap->maps[NZ](0.0, &zcomp, &zcurr, pmap->ctxs[NZ]);
    // Use one computational cell as the nominal difference step, with
    // second-order inward differences near the global endpoints.
    double dZ_dz = gkyl_position_map_slope(
      pmap, NZ, zcomp, comp_grid.dx[NZ], comp_grid.lower[NZ], comp_grid.upper[NZ]
    );
    double psi_min, psi_max;
    evcub->eval_cubic(0.0, (double[]){rmin, zcurr}, &psi_min, evcub->ctx);
    evcub->eval_cubic(0.0, (double[]){rmax, zcurr}, &psi_max, evcub->ctx);
    pctx.Z = zcurr;

    for (int ipsi = inp->nrange.lower[NPSI]; ipsi <= inp->nrange.upper[NPSI]; ++ipsi) {
      double psic = gk_geometry_node_coord(
        &comp_grid, &inp->local, &inp->global, &inp->nrange, NPSI, ipsi, num_nodes[NPSI], quad[NPSI]
      );
      double psi_map;
      pmap->maps[NPSI](0.0, &psic, &psi_map, pmap->ctxs[NPSI]);
      double dPsi_dpsi = gkyl_position_map_slope(
        pmap, NPSI, psic, comp_grid.dx[NPSI], comp_grid.lower[NPSI], comp_grid.upper[NPSI]
      );
      double psi_curr = sqrt_psi ? psi_map * psi_map : psi_map;
      bool on_axis = inp->include_axis && !quad[NPSI] && ipsi == inp->nrange.lower[NPSI] &&
                     inp->local.lower[NPSI] == inp->global.lower[NPSI];
      double radius = 0.0;
      if (on_axis) {
        psi_curr = 0.0;
      } else {
        pctx.psi = psi_curr;
        double f_lo = psi_min - psi_curr, f_hi = psi_max - psi_curr;
        double psi_tol = 16.0 * DBL_EPSILON * fabs(psi_curr);
        // Ridders requires a bracket. Without one it can report convergence
        // to an extrapolated radius (or even a point that is not a root).
        // Accept endpoint roots to roundoff before checking the signs.
        if (fabs(f_lo) <= psi_tol) {
          radius = rmin;
        } else if (fabs(f_hi) <= psi_tol) {
          radius = rmax;
        } else if ((f_lo < 0.0 && f_hi > 0.0) || (f_lo > 0.0 && f_hi < 0.0)) {
          struct gkyl_qr_res root = gkyl_ridders(psirz, &pctx, rmin, rmax, f_lo, f_hi, 100, 1e-10);
          if (root.status || !(root.res >= rmin && root.res <= rmax)) {
            status = false;
            goto cleanup;
          }
          radius = root.res;
        } else {
          status = false;
          goto cleanup;
        }
      }

      for (int ia = inp->nrange.lower[NAL]; ia <= inp->nrange.upper[NAL]; ++ia) {
        double alpha_comp = gk_geometry_node_coord(
          &comp_grid, &inp->local, &inp->global, &inp->nrange, NAL, ia, num_nodes[NAL], quad[NAL]
        );
        double alpha_curr;
        pmap->maps[NAL](0.0, &alpha_comp, &alpha_curr, pmap->ctxs[NAL]);
        double dAlpha_dalpha = gkyl_position_map_slope(
          pmap, NAL, alpha_comp, comp_grid.dx[NAL], comp_grid.lower[NAL], comp_grid.upper[NAL]
        );
        int idx[] = {ipsi, ia, iz};
        long loc = gkyl_range_idx(&inp->nrange, idx);
        double *rzp = gkyl_array_fetch(geo->nodes_rza, loc);
        rzp[R_NODE_I] = radius;
        rzp[Z_NODE_I] = zcurr;
        rzp[PHI_NODE_I] = alpha_curr;
        double *psi_coord = gkyl_array_fetch(geo->nodes_psi, loc);
        psi_coord[PSI_I] = psi_curr;
        struct gkyl_mirror_grid_gen_geom *geom = gkyl_array_fetch(geo->nodes_geom, loc);
        *geom = (struct gkyl_mirror_grid_gen_geom){0};
        double rz[] = {radius, zcurr};
        if (on_axis) {
          double fout[4];
          evcub->eval_cubic_wgrad2(0.0, rz, fout, evcub->ctx);
          // The radial/poloidal basis is singular at the axis. Keep the
          // existing defaults and the asymptotic psi ~ R^2 Jacobian.
          geom->dual[NPSI].x[R_I] = 1.0 / dPsi_dpsi;
          geom->dual[NAL].x[PHI_I] = 1.0 / dAlpha_dalpha;
          geom->dual[NZ].x[Z_I] = 1.0 / dZ_dz;
          geom->tang[NPSI].x[R_I] = dPsi_dpsi;
          geom->tang[NAL].x[PHI_I] = dAlpha_dalpha;
          geom->tang[NZ].x[Z_I] = dZ_dz;
          geom->Jc = sqrt_psi ? 0.0 : dPsi_dpsi * dAlpha_dalpha * dZ_dz / fout[D2PSI_RR_I];
          geom->B.x[Z_I] = fout[D2PSI_RR_I];
        } else {
          double fout[3];
          evcub->eval_cubic_wgrad(0.0, rz, fout, evcub->ctx);
          double radial_scale = dPsi_dpsi * (sqrt_psi ? 2.0 * floor_sqrt(fout[PSI_I]) : 1.0);
          geom->dual[NPSI].x[R_I] = fout[DPSI_R_I] / radial_scale;
          geom->dual[NPSI].x[Z_I] = fout[DPSI_Z_I] / radial_scale;
          geom->dual[NAL].x[PHI_I] = 1.0 / (radius * radius * dAlpha_dalpha);
          geom->dual[NZ].x[Z_I] = 1.0 / dZ_dz;
          geom->tang[NPSI].x[R_I] = radial_scale / fout[DPSI_R_I];
          geom->tang[NAL].x[PHI_I] = dAlpha_dalpha;
          // R(psi, M(z)): both components of the field-line tangent
          // carry dM/dz. This preserves e_3 dot grad(psi) = 0.
          geom->tang[NZ].x[R_I] = -fout[DPSI_Z_I] / fout[DPSI_R_I] * dZ_dz;
          geom->tang[NZ].x[Z_I] = dZ_dz;
          geom->Jc = radial_scale * radius / fout[DPSI_R_I] * dAlpha_dalpha * dZ_dz;
          geom->B.x[R_I] = -fout[DPSI_Z_I] / radius;
          geom->B.x[Z_I] = fout[DPSI_R_I] / radius;
          curlbhat_func(radius, zcurr, alpha_curr, evcub, &geom->curlbhat);
        }
      }
    }
  }
  const struct gkyl_mirror_grid_gen_geom *actual, const struct gkyl_mirror_grid_gen_geom *expected,
  double tol
)
{
  for (int dim = 0; dim < 3; ++dim) {
    for (int comp = 0; comp < 3; ++comp) {
      mirror_check_close(actual->tang[dim].x[comp], expected->tang[dim].x[comp], tol, "tangent");
      mirror_check_close(actual->dual[dim].x[comp], expected->dual[dim].x[comp], tol, "dual");
    }
    mirror_check_close(actual->B.x[dim], expected->B.x[dim], tol, "B");
    mirror_check_close(actual->curlbhat.x[dim], expected->curlbhat.x[dim], tol, "curl(bhat)");
  }
  mirror_check_close(actual->Jc, expected->Jc, tol, "Jacobian");
}

static void mirror_check_exact(
  const struct gkyl_mirror_grid_gen_inp *inp, const struct gkyl_mirror_grid_gen *geom, int kind,
  int order, const struct mirror_map_ctx *maps, double strength, double curvature
)
{
  TEST_CHECK(gkyl_mirror_grid_gen_fl_coord(geom) == inp->fl_coord);
  TEST_CHECK(gkyl_mirror_grid_gen_is_include_axis(geom) == inp->include_axis);
  bool sqrt_psi = inp->fl_coord == GKYL_GEOMETRY_MIRROR_GRID_GEN_SQRT_PSI_CART_Z;
  struct gkyl_range_iter iter;
  gkyl_range_iter_init(&iter, &inp->nrange);
  while (gkyl_range_iter_next(&iter)) {
    double mapped[3], slope[3];
    int global_node[3];
    for (int dim = 0; dim < 3; ++dim) {
      int count = mirror_nodes_per_cell(kind, dim, order);
      bool quad = kind == -2 || (kind >= 0 && dim != kind);
      global_node[dim] = iter.idx[dim] - inp->nrange.lower[dim] +
                         count * (inp->local.lower[dim] - inp->global.lower[dim]);
      double xc = mirror_coordinate(
        maps[dim].lower, maps[dim].upper, inp->comp_grid->cells[dim], global_node[dim], count, quad
      );
      mapped[dim] = maps[dim].shift + xc * (maps[dim].scale + maps[dim].curvature * xc);
      slope[dim] = maps[dim].scale + 2.0 * maps[dim].curvature * xc;
    }
    bool axis = inp->include_axis && (kind == -1 || kind == 0) && global_node[0] == 0;
    double flux = axis ? 0.0 : sqrt_psi ? mapped[0] * mapped[0] : mapped[0];
    double height = mapped[2], factor = 1.0 + curvature * height * height;
    double radius = sqrt(2.0 * flux / (strength * factor));
    double radial_scale = slope[0] * (sqrt_psi ? 2.0 * mapped[0] : 1.0);
    long loc = gkyl_range_idx(&inp->nrange, iter.idx);
    const double *rza = gkyl_array_cfetch(geom->nodes_rza, loc);
    const double *psi = gkyl_array_cfetch(geom->nodes_psi, loc);
    const struct gkyl_mirror_grid_gen_geom *actual = gkyl_array_cfetch(geom->nodes_geom, loc);
    mirror_check_close(rza[0], radius, 2e-11, "R");
    mirror_check_close(rza[1], height, 2e-14, "Z");
    mirror_check_close(rza[2], mapped[1], 2e-14, "phi");
    mirror_check_close(psi[0], flux, 2e-14, "psi");

    struct gkyl_mirror_grid_gen_geom expected = {0};
    expected.B.x[0] = strength * curvature * radius * height;
    expected.B.x[2] = -strength * factor;
    expected.tang[1].x[1] = slope[1];
    expected.tang[2].x[2] = slope[2];
    expected.dual[2].x[2] = 1.0 / slope[2];
    expected.Jc = radial_scale * slope[1] * slope[2] / (strength * factor);
    if (axis) {
      // The public representation deliberately uses finite placeholder bases
      // at the cylindrical singularity, while B and J use their true limits.
      expected.tang[0].x[0] = slope[0];
      expected.dual[0].x[0] = 1.0 / slope[0];
      expected.dual[1].x[1] = 1.0 / slope[1];
    } else {
      expected.tang[0].x[0] = radial_scale / (strength * radius * factor);
      expected.tang[2].x[0] = -curvature * radius * height * slope[2] / factor;
      expected.dual[0].x[0] = strength * radius * factor / radial_scale;
      expected.dual[0].x[2] = strength * curvature * radius * radius * height / radial_scale;
      expected.dual[1].x[1] = 1.0 / (radius * radius * slope[1]);
      // Closed form of (d_Z b_R - d_R b_Z)/R. Independent of field strength.
      double norm2 = factor * factor + curvature * curvature * radius * radius * height * height;
      expected.curlbhat.x[1] =
        curvature * factor * (1.0 - 2.0 * curvature * height * height) / pow(norm2, 1.5);
    }
    mirror_check_geom(actual, &expected, 2e-9);
  }
}

static void mirror_check_partition(
  const struct gkyl_mirror_grid_gen_inp *inp, const struct gkyl_mirror_grid_gen *geom,
  const struct gkyl_range *full_nodes, const struct gkyl_mirror_grid_gen *full, int kind, int order
)
{
    for (int ip = nrange_quad_interior.lower[PSI_IDX] + 3;
