        double theta =
          calc_running_coord(theta_lo, ia - nrange_quad_interior.lower[TH_IDX], grid.dx[TH_IDX]);
        double xn[3] = {psi, alpha, theta};
        double fout[9];
        exact_normals_pmap(0.0, xn, fout, 0);
        for (int i = 0; i < 9; ++i) {
