#include <gkyl_calc_metric_mirror.h>
#include <gkyl_calc_metric_mirror_priv.h>
#include <gkyl_alloc.h>
#include <gkyl_array.h>
#include <gkyl_range.h>
#include <gkyl_nodal_ops.h>
#include <gkyl_array_ops_priv.h>
#include <gkyl_mirror_grid_gen.h>
#include <gkyl_math.h>
#include <gkyl_dg_bin_ops.h>

gkyl_calc_metric_mirror *gkyl_calc_metric_mirror_new(
  const struct gkyl_basis *cbasis, const struct gkyl_rect_grid *grid,
  const struct gkyl_range *local, const struct gkyl_range *local_ext, bool use_gpu
)
{
  gkyl_calc_metric_mirror *up = gkyl_malloc(sizeof(gkyl_calc_metric_mirror));
  up->cbasis = cbasis;
  up->cdim = cbasis->ndim;
  up->cnum_basis = cbasis->num_basis;
  up->poly_order = cbasis->poly_order;
  up->grid = grid;
  up->use_gpu = use_gpu;
  up->num_cells = up->grid->cells;
  up->n2m = gkyl_nodal_ops_new(up->cbasis, up->grid, up->use_gpu);

  up->local = *local;
  up->local_ext = *local_ext;
  return up;
}

static inline double calc_metric(double dxdz[3][3], int i, int j)
{
  double sum = 0;
  for (int k = 0; k < 3; ++k) {
    sum += dxdz[k][i - 1] * dxdz[k][j - 1];
  }
  return sum;
}

// Calculates e^1 = e_2 x e_3 /J
static inline void calc_dual(double J, const double e_2[3], const double e_3[3], double e1[3])
{
  e1[0] = (e_2[1] * e_3[2] - e_2[2] * e_3[1]) / J;
  e1[1] = -(e_2[0] * e_3[2] - e_2[2] * e_3[0]) / J;
  e1[2] = (e_2[0] * e_3[1] - e_2[1] * e_3[0]) / J;
}

void gkyl_calc_metric_mirror_advance(
  gkyl_calc_metric_mirror *up, struct gk_geometry *gk_geom, struct gkyl_mirror_grid_gen *mirror_grid
)
{
  enum { PSI_IDX, AL_IDX, TH_IDX }; // Arrangement of computational coordinates.
  enum { R_IDX, Z_IDX, PHI_IDX }; // Arrangement of cylindrical coordinates.
  int cidx[3];
  for (int ia = gk_geom->nrange_corn.lower[AL_IDX]; ia <= gk_geom->nrange_corn.upper[AL_IDX];
       ++ia) {
    for (int ip = gk_geom->nrange_corn.lower[PSI_IDX]; ip <= gk_geom->nrange_corn.upper[PSI_IDX];
         ++ip) {
      for (int it = gk_geom->nrange_corn.lower[TH_IDX]; it <= gk_geom->nrange_corn.upper[TH_IDX];
           ++it) {
        cidx[PSI_IDX] = ip;
        cidx[AL_IDX] = ia;
        cidx[TH_IDX] = it;

        // First fetch the mirror stuff at this location
        const double *mirror_rza_n =
          gkyl_array_cfetch(mirror_grid->nodes_rza, gkyl_range_idx(&gk_geom->nrange_corn, cidx));
        const double *mirror_psi_n =
          gkyl_array_cfetch(mirror_grid->nodes_psi, gkyl_range_idx(&gk_geom->nrange_corn, cidx));
        const struct gkyl_mirror_grid_gen_geom *mirror_geo_n =
          gkyl_array_cfetch(mirror_grid->nodes_geom, gkyl_range_idx(&gk_geom->nrange_corn, cidx));

        // Next fetch the gk_geometry nodal values at this location
        double *mc2p_n = gkyl_array_fetch(
          gk_geom->geo_corn.mc2p_nodal, gkyl_range_idx(&gk_geom->nrange_corn, cidx)
        );
        double *mc2nu_pos_n = gkyl_array_fetch(
          gk_geom->geo_corn.mc2nu_pos_nodal, gkyl_range_idx(&gk_geom->nrange_corn, cidx)
        );
        double *bmag_n = gkyl_array_fetch(
          gk_geom->geo_corn.bmag_nodal, gkyl_range_idx(&gk_geom->nrange_corn, cidx)
        );

        // Set mapc2p
        mc2p_n[0] = mirror_rza_n[0]; // R
        mc2p_n[1] = mirror_rza_n[1]; // Z
        mc2p_n[2] = mirror_rza_n[2]; // PHI
        // Set mapc2nu
        mc2nu_pos_n[0] = mirror_psi_n[0];
        mc2nu_pos_n[1] = mirror_rza_n[2];
        mc2nu_pos_n[2] = mirror_rza_n[1];
        // Set bmag
        struct gkyl_vec3 B_cart =
          gkyl_vec3_polar_con_to_cart(mirror_rza_n[0], mirror_rza_n[2], mirror_geo_n->B);
        bmag_n[0] = gkyl_vec3_len(B_cart);
      }
    }
  }
  gkyl_nodal_ops_n2m(
    up->n2m, up->cbasis, up->grid, &gk_geom->nrange_corn, &gk_geom->local, 3,
    gk_geom->geo_corn.mc2p_nodal, gk_geom->geo_corn.mc2p, false
  );
  gkyl_nodal_ops_n2m(
    up->n2m, up->cbasis, up->grid, &gk_geom->nrange_corn, &gk_geom->local, 3,
    gk_geom->geo_corn.mc2nu_pos_nodal, gk_geom->geo_corn.mc2nu_pos, false
  );
  gkyl_nodal_ops_n2m(
    up->n2m, up->cbasis, up->grid, &gk_geom->nrange_corn, &gk_geom->local, 1,
    gk_geom->geo_corn.bmag_nodal, gk_geom->geo_corn.bmag, false
  );

  // Need 1/B for LBO collisions, computed weakly.
  gkyl_dg_inv_op_range(
    up->cbasis, 0, gk_geom->geo_corn.bmag_inv, 0, gk_geom->geo_corn.bmag, &gk_geom->local
  );
}

void gkyl_calc_metric_mirror_advance_interior(
  gkyl_calc_metric_mirror *up, struct gk_geometry *gk_geom, struct gkyl_mirror_grid_gen *mirror_grid
)
{
  enum { PSI_IDX, AL_IDX, TH_IDX }; // arrangement of computational coordinates
  enum { R_IDX, Z_IDX, PHI_IDX }; // arrangement of cylindrical coordinates
  int cidx[3];
  for (int ia = gk_geom->nrange_int.lower[AL_IDX]; ia <= gk_geom->nrange_int.upper[AL_IDX]; ++ia) {
    for (int ip = gk_geom->nrange_int.lower[PSI_IDX]; ip <= gk_geom->nrange_int.upper[PSI_IDX];
         ++ip) {
      for (int it = gk_geom->nrange_int.lower[TH_IDX]; it <= gk_geom->nrange_int.upper[TH_IDX];
           ++it) {
        double *bioverJB_n = gkyl_array_fetch(
          gk_geom->geo_int.bioverJB_nodal, gkyl_range_idx(&gk_geom->nrange_int, cidx)
        );

        // Set mapc2p
        mc2p_n[0] = mirror_rza_n[0]; // R
        mc2p_n[1] = mirror_rza_n[1]; // Z
        mc2p_n[2] = mirror_rza_n[2]; // PHI
        // Set bmag
        struct gkyl_vec3 B_cart =
          gkyl_vec3_polar_con_to_cart(mirror_rza_n[0], mirror_rza_n[2], mirror_geo_n->B);
        bmag_n[0] = gkyl_vec3_len(B_cart);
        // Set Jacobian
        jFld_n[0] = mirror_geo_n->Jc;
        // Set curl(bhat)
        struct gkyl_vec3 curlbhat_cart =
          gkyl_vec3_polar_con_to_cart(mirror_rza_n[0], mirror_rza_n[2], mirror_geo_n->curlbhat);
        curlbhat_n[0] = curlbhat_cart.x[0];
        curlbhat_n[1] = curlbhat_cart.x[1];
        curlbhat_n[2] = curlbhat_cart.x[2];

        // Set tangents and duals
        for (int ivec = 0; ivec < 3; ivec++) {
          struct gkyl_vec3 tan =
            gkyl_vec3_polar_con_to_cart(mirror_rza_n[0], mirror_rza_n[2], mirror_geo_n->tang[ivec]);
          struct gkyl_vec3 dual =
            gkyl_vec3_polar_con_to_cart(mirror_rza_n[0], mirror_rza_n[2], mirror_geo_n->dual[ivec]);
          tanvecFld_n[ivec * 3 + 0] = tan.x[0];
          tanvecFld_n[ivec * 3 + 1] = tan.x[1];
          tanvecFld_n[ivec * 3 + 2] = tan.x[2];
          dualFld_n[ivec * 3 + 0] = dual.x[0];
          dualFld_n[ivec * 3 + 1] = dual.x[1];
          dualFld_n[ivec * 3 + 2] = dual.x[2];
        }
        // Set metric tensor
        int count = 0;
        for (int i = 0; i < 3; ++i) {
          for (int j = 0; j < 3; ++j) {
            if (i > j) {
              continue;
            }
            gFld_n[count] = tanvecFld_n[3 * i + 0] * tanvecFld_n[3 * j + 0] +
                            tanvecFld_n[3 * i + 1] * tanvecFld_n[3 * j + 1] +
                            tanvecFld_n[3 * i + 2] * tanvecFld_n[3 * j + 2];
            count++;
          }
        }

        // Now set derived geometric quantities
        double R = mc2p_n[R_IDX];
        double Z = mc2p_n[Z_IDX];
        double phi = mc2p_n[PHI_IDX];
        double J = jFld_n[0];

        // Use the magnetic vector: bhat can oppose the third coordinate tangent.
        for (int i = 0; i < 3; ++i) {
          bcartFld_n[i] = B_cart.x[i] / bmag_n[0];
        }
        for (int i = 0; i < 3; ++i) {
          biFld_n[i] = tanvecFld_n[3 * i] * bcartFld_n[0] + tanvecFld_n[3 * i + 1] * bcartFld_n[1] +
                       tanvecFld_n[3 * i + 2] * bcartFld_n[2];
        }

        double norm1 = sqrt(
          dualFld_n[0] * dualFld_n[0] + dualFld_n[1] * dualFld_n[1] + dualFld_n[2] * dualFld_n[2]
        );
        double norm2 = sqrt(
          dualFld_n[3] * dualFld_n[3] + dualFld_n[4] * dualFld_n[4] + dualFld_n[5] * dualFld_n[5]
        );
        double norm3 = sqrt(
          dualFld_n[6] * dualFld_n[6] + dualFld_n[7] * dualFld_n[7] + dualFld_n[8] * dualFld_n[8]
        );

        dualmagFld_n[0] = norm1;
        dualmagFld_n[1] = norm2;
        dualmagFld_n[2] = norm3;

        // Set normal vectors
        normFld_n[0] = dualFld_n[0] / norm1;
        normFld_n[1] = dualFld_n[1] / norm1;
        normFld_n[2] = dualFld_n[2] / norm1;

        normFld_n[3] = dualFld_n[3] / norm2;
        normFld_n[4] = dualFld_n[4] / norm2;
        normFld_n[5] = dualFld_n[5] / norm2;

        normFld_n[6] = dualFld_n[6] / norm3;
        normFld_n[7] = dualFld_n[7] / norm3;
        normFld_n[8] = dualFld_n[8] / norm3;

        // Set e^m \dot curl(bhat)
        dualcurlbhat_n[0] = dualFld_n[0] * curlbhat_n[0] + dualFld_n[1] * curlbhat_n[1] +
                            dualFld_n[2] * curlbhat_n[2];
        dualcurlbhat_n[1] = dualFld_n[3] * curlbhat_n[0] + dualFld_n[4] * curlbhat_n[1] +
                            dualFld_n[5] * curlbhat_n[2];
        dualcurlbhat_n[2] = dualFld_n[6] * curlbhat_n[0] + dualFld_n[7] * curlbhat_n[1] +
                            dualFld_n[8] * curlbhat_n[2];

        // Set e^3 \dot B
        B3_n[0] =
          dualFld_n[6] * B_cart.x[0] + dualFld_n[7] * B_cart.x[1] + dualFld_n[8] * B_cart.x[2];

        // Set e^m \dot curl(bhat)/|B|.
        dualcurlbhatoverB_n[0] = dualcurlbhat_n[0] / bmag_n[0];
        dualcurlbhatoverB_n[1] = dualcurlbhat_n[1] / bmag_n[0];
        dualcurlbhatoverB_n[2] = dualcurlbhat_n[2] / bmag_n[0];

        // Signed B^3/|B| controls streaming along the third coordinate.
        rtg33inv_n[0] = B3_n[0] / bmag_n[0];

        // set b_i/JB
        for (int i = 0; i < 3; ++i) {
          bioverJB_n[i] = biFld_n[i] / (J * bmag_n[0]);
        }
      }
    }
  }

  gkyl_nodal_ops_n2m(
    up->n2m, up->cbasis, up->grid, &gk_geom->nrange_int, &gk_geom->local, 3,
    gk_geom->geo_int.mc2p_nodal, gk_geom->geo_int.mc2p, true
  );
  gkyl_nodal_ops_n2m(
    up->n2m, up->cbasis, up->grid, &gk_geom->nrange_int, &gk_geom->local, 1,
    gk_geom->geo_int.bmag_nodal, gk_geom->geo_int.bmag, true
  );
  gkyl_nodal_ops_n2m(
    up->n2m, up->cbasis, up->grid, &gk_geom->nrange_int, &gk_geom->local, 6,
    gk_geom->geo_int.g_ij_nodal, gk_geom->geo_int.g_ij, true
          gkyl_range_idx(&gk_geom->nrange_surf[dir], cidx)
        );

        // Set mapc2p
        mc2p_n[0] = mirror_rza_n[0]; // R
        mc2p_n[1] = mirror_rza_n[1]; // Z
        mc2p_n[2] = mirror_rza_n[2]; // PHI
        // Set bmag
        struct gkyl_vec3 B_cart =
          gkyl_vec3_polar_con_to_cart(mirror_rza_n[0], mirror_rza_n[2], mirror_geo_n->B);
        bmag_n[0] = gkyl_vec3_len(B_cart);
        // Set Jacobian
        jFld_n[0] = mirror_geo_n->Jc;
        // Set curl(bhat)
        struct gkyl_vec3 curlbhat_cart =
          gkyl_vec3_polar_con_to_cart(mirror_rza_n[0], mirror_rza_n[2], mirror_geo_n->curlbhat);
        curlbhat_n[0] = curlbhat_cart.x[0];
        curlbhat_n[1] = curlbhat_cart.x[1];
        curlbhat_n[2] = curlbhat_cart.x[2];
        // Set tangents and duals
        for (int ivec = 0; ivec < 3; ivec++) {
          struct gkyl_vec3 tan =
            gkyl_vec3_polar_con_to_cart(mirror_rza_n[0], mirror_rza_n[2], mirror_geo_n->tang[ivec]);
          struct gkyl_vec3 dual =
            gkyl_vec3_polar_con_to_cart(mirror_rza_n[0], mirror_rza_n[2], mirror_geo_n->dual[ivec]);
          tanvecFld_n[ivec * 3 + 0] = tan.x[0];
          tanvecFld_n[ivec * 3 + 1] = tan.x[1];
          tanvecFld_n[ivec * 3 + 2] = tan.x[2];
          dualFld_n[ivec * 3 + 0] = dual.x[0];
          dualFld_n[ivec * 3 + 1] = dual.x[1];
          dualFld_n[ivec * 3 + 2] = dual.x[2];
        }
        // Set metric tensor
        int count = 0;
        for (int i = 0; i < 3; ++i) {
          for (int j = 0; j < 3; ++j) {
            if (i > j) {
              continue;
            }
            gFld_n[count] = tanvecFld_n[3 * i + 0] * tanvecFld_n[3 * j + 0] +
                            tanvecFld_n[3 * i + 1] * tanvecFld_n[3 * j + 1] +
                            tanvecFld_n[3 * i + 2] * tanvecFld_n[3 * j + 2];
            count++;
          }
        }

        // Set derived quantities
        double R = mc2p_n[R_IDX];
        double Z = mc2p_n[Z_IDX];
        double J = jFld_n[0];
        double phi = mc2p_n[PHI_IDX];

        // Calculate bhat and its covariant components from the magnetic vector.
        for (int i = 0; i < 3; ++i) {
          bcartFld_n[i] = B_cart.x[i] / bmag_n[0];
        }
        for (int i = 0; i < 3; ++i) {
          biFld_n[i] = tanvecFld_n[3 * i] * bcartFld_n[0] + tanvecFld_n[3 * i + 1] * bcartFld_n[1] +
                       tanvecFld_n[3 * i + 2] * bcartFld_n[2];
        }

        // cmag is a magnitude; reversing B leaves it and J|B| unchanged.
        cmagFld_n[0] = jFld_n[0] * bmag_n[0] / sqrt(gFld_n[5]);
        double *jtotinvFld_n = gkyl_array_fetch(
          gk_geom->geo_surf[dir].jacobtot_inv_nodal,
          gkyl_range_idx(&gk_geom->nrange_surf[dir], cidx)
        );
        jtotinvFld_n[0] = 1.0 / (jFld_n[0] * bmag_n[0]);

        double norm1 = sqrt(
          dualFld_n[0] * dualFld_n[0] + dualFld_n[1] * dualFld_n[1] + dualFld_n[2] * dualFld_n[2]
        );
        double norm2 = sqrt(
          dualFld_n[3] * dualFld_n[3] + dualFld_n[4] * dualFld_n[4] + dualFld_n[5] * dualFld_n[5]
        );
        double norm3 = sqrt(
          dualFld_n[6] * dualFld_n[6] + dualFld_n[7] * dualFld_n[7] + dualFld_n[8] * dualFld_n[8]
        );

        dualmagFld_n[0] = norm1;
        dualmagFld_n[1] = norm2;
        dualmagFld_n[2] = norm3;

        // Set normal vectors
        normFld_n[0] = dualFld_n[0] / norm1;
        normFld_n[1] = dualFld_n[1] / norm1;
        normFld_n[2] = dualFld_n[2] / norm1;

        normFld_n[3] = dualFld_n[3] / norm2;
        normFld_n[4] = dualFld_n[4] / norm2;
        normFld_n[5] = dualFld_n[5] / norm2;

        normFld_n[6] = dualFld_n[6] / norm3;
        normFld_n[7] = dualFld_n[7] / norm3;
        normFld_n[8] = dualFld_n[8] / norm3;

        // Set lenr
        lenr_n[0] = J * dualmagFld_n[dir];

        // Set n^3 \dot B
        B3_n[0] =
          normFld_n[6] * B_cart.x[0] + normFld_n[7] * B_cart.x[1] + normFld_n[8] * B_cart.x[2];

        // Set n^m \dot curl(bhat)
        normcurlbhat_n[0] = normFld_n[3 * dir + 0] * curlbhat_n[0] +
                            normFld_n[3 * dir + 1] * curlbhat_n[1] +
                            normFld_n[3 * dir + 2] * curlbhat_n[2];
      }
    }
  }
}

void gkyl_calc_metric_mirror_release(gkyl_calc_metric_mirror *up)
struct gk_geometry *gkyl_gk_geometry_mirror_new(struct gkyl_gk_geometry_inp *geometry_inp)
{
  struct gk_geometry *gk_geom_3d;
  struct gk_geometry *gk_geom;

  // First construct the uniform 3d geometry
  gk_geom_3d = gk_geometry_mirror_init(geometry_inp);
  if (geometry_inp->position_map->id == GKYL_PMAP_CONSTANT_DB_POLYNOMIAL ||
      geometry_inp->position_map->id == GKYL_PMAP_CONSTANT_DB_NUMERIC) {
    // The array mc2nu is computed using the uniform geometry, so we need to deflate it
    // Must deflate the 3D uniform geometry in order for the allgather to work
    if (geometry_inp->grid.ndim < 3) {
      gk_geom = gkyl_gk_geometry_deflate(gk_geom_3d, geometry_inp);
    } else {
      gk_geom = gkyl_gk_geometry_acquire(gk_geom_3d);
    }

    gkyl_position_map_set_bmag(
      geometry_inp->position_map, geometry_inp->comm, gk_geom->geo_int.bmag
    );

    gkyl_gk_geometry_release(gk_geom_3d); // release temporary 3d geometry
    gkyl_gk_geometry_release(gk_geom); // release 3d geometry

    // Construct the non-uniform grid
    gk_geom_3d = gk_geometry_mirror_init(geometry_inp);
  }
  return gk_geom_3d;
}
