        .position_map = pmap,
        .grid = grid,
        .local = local,
        .local_ext = ext,
        .global = local,
        .global_ext = ext,
        .basis = basis,
        .geo_grid = grid,
        .geo_local = local,
        .geo_local_ext = ext,
        .geo_global = local,
        .geo_global_ext = ext,
