          {"rtg33inv", 1, surface ? NULL : vol->rtg33inv_nodal, surface ? NULL : vol->rtg33inv},
          {"bioverJB", 3, surface ? NULL : vol->bioverJB_nodal, surface ? NULL : vol->bioverJB},
          {"cmag", 1, surface ? face->cmag_nodal : NULL, surface ? face->cmag : vol->cmag}
        };
