  double psi = r * r / 4;
  fout[0] = r * r / 4; // g_11
  fout[1] = 0.0; // g_12
  fout[2] = 0.0; // g_13
  fout[3] = 1 / psi / 4; // g_22
  fout[4] = 0.0; // g_23
  fout[5] = 1.0; // g_33
