  fout[0] = cos(alpha);
  fout[1] = sin(alpha);
  fout[2] = 0.0;
  fout[3] = -sin(alpha);
  fout[4] = cos(alpha);
  fout[5] = 0.0;
  fout[6] = 0.0;
  fout[7] = 0.0;
  fout[8] = 1.0;
}

